edu1:{tag:'Education · 2024—2026',title:'Jingdezhen Ceramic University · Sculpture, Second Bachelor Degree',
 meta:[['School','School of Fine Arts'],['Length','Two years (full-time, national entrance)'],['Credits','61'],['Average mark','85.2'],['GPA','3.52 / 4']],
 body:`<p><b style="color:var(--gold-bright);font-weight:400">What is a "second bachelor degree"?</b> — a second undergraduate degree pursued, after a first bachelor degree, through the national unified entrance route: a two-year, full-time programme whose degree certificate carries <b style="color:var(--gold-bright);font-weight:400">the same legal standing</b> as the first one. In international terms (EQF / UK-US frameworks) it sits at <i style="font-family:var(--latin)">Bachelor's degree (undergraduate)</i> level. In other words, a return to the undergraduate studio carrying all the research training of a master's degree — from art historian back to maker.</p>
 <div class="sub">Key courses and marks</div><ul>
 <li>Materials and Concepts — 93</li><li>Traditional Sculpture — 90</li><li>Ceramic Sculpture — 88</li><li>Xieyi (Freehand) Sculpture — 88</li>
 <li>Clay Modelling: Figure — 85</li><li>Clay Modelling: Draped Figure — 84</li><li>Digital Sculpture — 84</li><li>Clay Modelling: Bust — 83</li>
 <li>Ceramic Forming Techniques — 81</li><li>Thesis / Final Work and Defence — Good</li></ul>
 <div class="sub">Final project · ceramic sculpture An Illustrated Guide to Chinese Lion Dance</div><ul><li>Graduation project for the 2026 sculpture cohort: eight ceramic lion heads and masks forming a series that builds a "visible, touchable, preservable three-dimensional ethnography" for the lesser-known lion dance traditions beyond the Cantonese style (northern, Hakka, Teochew and others); using art anthropology, iconographic folklore and material-culture narrative, and carrying the whole process from field material, drawings and clay maquettes through forming, drying, firing and gilding.</li></ul>
 <a class="dl" href="assets/thesis_lion.pdf" target="_blank">Graduation defence slides (PDF) ↓</a>
 <p class="dim">Based in Jingdezhen, Jiangxi, working in parallel with the studio practice in Longquan, Zhejiang.</p>`,
 tags:['Second bachelor degree','Sculpture','Ceramic forming','Materials and concepts','Xieyi sculpture']},
edu2:{tag:'Education · 2022—2024',title:'Macau University of Science and Technology · MA in Fine Arts (Art History)',
 meta:[['Ranking','THE 251 / QS 464'],['Faculty','Faculty of Humanities and Arts'],['Degree','Master of Fine Arts (Art History)']],
 body:`<p>Systematic training in art-historical research, entering the study of visual art through historical method, with a focus on funerary architectural imagery and cross-cultural art history; the thesis was defended in June 2024 and the degree of Master of Fine Arts was conferred by the university's teaching committee.</p>
 <div class="sub">Key courses (official transcript)</div><ul>
 <li>Research Methods in Art History</li><li>Art History</li><li>Topics in Western Art History</li>
 <li>Topics in Art Theory</li><li>Cultural Topics</li><li>Internship / Academic Activities</li></ul>
 <div class="sub">Thesis</div><ul><li>A Study of Macao Funerary Architectural Imagery (A Study on the Architectural Images of Tombstones in Macao): using architectural ethnography, documentary research, iconography and iconology, and interdisciplinary method, it surveys the tombstone architecture of the 17 cemeteries extant in Macao — structure and form, and the identification, meaning and application of their imagery. Defended in June 2024; held in the MUST Library institutional thesis repository with abstracts in Chinese and English.</li></ul>`,
 tags:['Art history','Iconography','Macao studies','Funerary architecture']},
edu3:{tag:'Education · 2018—2022',title:'Guangdong University of Petrochemical Technology · BA in History',
 meta:[['Faculty','School of Humanities and Law'],['Major','History']],
 body:`<p>Systematic undergraduate training in historical method, covering documentary work, fieldwork and oral history — the foundation of all later research and practice.</p>
 <div class="sub">Key courses</div><ul><li>General History of China — 94</li><li>General History of the World — 95</li><li>Introduction to Historiography — 88</li>
 <li>Literary Theory — 94</li><li>College Japanese II — 92</li></ul>
 <div class="sub">Honours and thesis</div><ul><li>First-Class Scholarship; Merit Student; Outstanding Graduate</li><li>Thesis: On the Causes of the Failure of Japanese Socialism</li></ul>`,
 tags:['History','Oral history','Archival work']},

